import std.io

pub type AppError = Failed(String)

interface A { fn a(self) -> Int64 }
interface B { fn b(self) -> Int64 }

record R { x: Int64 }

impl A for R {
    fn a(self) -> Int64 { 1 }
}
impl B for R {
    fn b(self) -> Int64 { 2 }
}

pub fn main() effect io -> Result<(), AppError> {
    let p = Dyn<A>(R { x: 1 })
    let q = Dyn<B>(R { x: 2 })
    let s = p.a()
    let t = q.b()
    io.println("${s}")
    io.println("${t}")
    return Ok(())
}
